contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test function driven by inputs
    function run(uint256 advanceTime, address newDistributeAddr, uint256 seedAmount) public payable {
        // Preconditions: ensure we have some tokens in this contract so we can fund c if needed
        // seedAmount is the amount we will transfer into c from msg.sender (which is this contract's deployer externally),
        // but since the checker deploys c fresh and this contract is its deployer, we cannot rely on external token balances.
        // Instead we only interact through c's public API. We'll attempt to set caller and distributeAddress via setCaller and setDistributeAddress
        // setCaller is onlyOwner; this test contract is the owner (it deployed c), so calls will succeed.

        // set a caller (cfo) to this contract so distributeToken can be called by this contract; use this contract's address
        c.setCaller(address(this));

        // set the distribute address to the provided input
        c.setDistributeAddress(newDistributeAddr);

        // Read before-values
        uint256 totalBefore = c.totalSupply();
        uint256 balanceContractBefore = c.balanceOf(address(c));
        uint256 balanceDestBefore = c.balanceOf(newDistributeAddr);

        // Try to run distributeTokenPeriodic and capture whether it reverted
        bool reverted;
        try c.distributeTokenPeriodic() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balanceContractAfter = c.balanceOf(address(c));
        uint256 balanceDestAfter = c.balanceOf(newDistributeAddr);

        // The general rule asserted:
        // - totalSupply never changes regardless of success or revert
        // - if call succeeded then either (balance at distributeAddress increased by distributeAmount and contract balance decreased by that amount)
        //   OR (if contract lacked tokens, call would have reverted and balances unchanged)
        // We cannot read distributeAmount directly (not public), but contract exposes distributeAmount as a private variable; however distributeAmount is not accessible.
        // Instead we express the invariant: totalSupply unchanged AND if not reverted then (balanceDestAfter >= balanceDestBefore && balanceContractAfter <= balanceContractBefore)
        // and the net moved amount equals balanceDestAfter - balanceDestBefore and equals balanceContractBefore - balanceContractAfter.

        assert(
            // total supply invariant
            totalAfter == totalBefore
            && (
                reverted
                ? (
                    // on revert, balances should be unchanged
                    balanceContractAfter == balanceContractBefore && balanceDestAfter == balanceDestBefore
                )
                : (
                    // on success, destination gained some tokens and contract lost the same amount
                    balanceDestAfter >= balanceDestBefore
                    && balanceContractAfter <= balanceContractBefore
                    && (balanceDestAfter - balanceDestBefore) == (balanceContractBefore - balanceContractAfter)
                )
            )
        );
    }

    // receive to accept ETH if needed
    receive() external payable {}
}

