contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test function driven by inputs
    function run(address newDistributeAddr) public payable {
        require(newDistributeAddr != address(0));

        // This test contract deployed c, so it is the owner and can call setCaller
        // Make this contract the authorized caller (cfo) so we can invoke distributeToken
        c.setCaller(address(this));

        // Ensure the contract has enough balance for a successful distribute: transfer tokens from msg.sender (the owner) to the contract
        // The deployer of c is this test contract (per problem statement), and it also was minted initial supply, so it can transfer
        // Read distributeAmount from c by calling a view via pattern: there's no getter for distributeAmount (it's private), so use expected behavior: distributeToken requires contract balance >= distributeAmount
        // We will first set the distributeAddress then ensure contract has at least c.balanceOf(address(this)) >= c.balanceOf(address(this)) (no-op). To guarantee enough balance, transfer a large amount from this (owner) to c.

        // Transfer a large amount (1e24) from this test contract (owner) to the token contract address to ensure balance at c is sufficient for distributeToken
        // Note: transfer is a public function on ERC20; calling c.transfer will attempt to move tokens from this contract's balance (it is the owner and has initial supply)
        bool ok = c.transfer(address(c), 1e24);
        // transfer may revert in some scenarios; require it succeeded or else the subsequent logic handles revert when calling distributeToken.
        // Set the distribute address to the provided input
        c.setDistributeAddress(newDistributeAddr);

        // Read before-values
        uint256 totalBefore = c.totalSupply();
        uint256 balanceContractBefore = c.balanceOf(address(c));
        uint256 balanceDestBefore = c.balanceOf(newDistributeAddr);

        // Attempt to call distributeToken and capture revert status
        bool reverted;
        try c.distributeToken() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balanceContractAfter = c.balanceOf(address(c));
        uint256 balanceDestAfter = c.balanceOf(newDistributeAddr);

        // Assert the general rule:
        // - totalSupply must never change
        // - if reverted: balances unchanged
        // - if not reverted: dest gained exactly distributeAmount and contract lost exactly distributeAmount
        // Because distributeAmount is a private variable with fixed value 2000 * 1e18 in the contract, assert using that constant
        uint256 distributeAmount = 2000 * 1e18;

        assert(
            totalAfter == totalBefore
            && (
                reverted
                ? (balanceContractAfter == balanceContractBefore && balanceDestAfter == balanceDestBefore)
                : (
                    balanceDestAfter == balanceDestBefore + distributeAmount
                    && balanceContractAfter + distributeAmount == balanceContractBefore
                )
            )
        );
    }

    receive() external payable {}
}
